*{box-sizing:border-box}body{background:var(--bg);color:var(--fg);font:14px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif;margin:0;padding:0 32px}button,select{font:inherit}button{min-width:44px;min-height:44px;padding:10px 20px;border-radius:8px;border:1px solid transparent;background:var(--ac);color:#fff;font-weight:600;cursor:pointer;transition:background .18s,transform .18s}button:hover{background:#244934}button:active{transform:translateY(1px)}button:disabled{opacity:.5;cursor:default}button.o{background:transparent;color:var(--fg);border-color:var(--bd)}button.o:hover{background:var(--soft)}:focus-visible{outline:3px solid #b2843b;outline-offset:3px}h1,h2,p{margin:0}h1{font-size:32px;line-height:1.2;letter-spacing:-.035em;font-weight:600}h2{font-size:24px;line-height:1.2;letter-spacing:-.025em;font-weight:600}.top,main,footer{max-width:1120px;margin:auto}.top{min-height:100px;display:flex;align-items:center;gap:32px;border-bottom:1px solid var(--bd)}.brand{display:flex;gap:12px;align-items:center;text-decoration:none;color:var(--fg);font-size:20px;font-weight:600;letter-spacing:-.04em}.brand svg{width:40px;height:40px;fill:none;stroke:var(--ac);stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}.brand small{display:block;color:var(--muted);font-size:12px;font-weight:400;letter-spacing:.03em;margin-top:2px}.top nav{display:flex;margin-left:auto;gap:4px}.top nav button{background:transparent;color:var(--fg);font-weight:400;padding:10px 16px}.top nav button:hover{background:var(--soft)}.money{border-left:1px solid var(--bd);padding-left:24px;min-width:100px}.money>span{font-size:12px;color:var(--muted)}.money>div{font-size:20px}.money b{font-weight:600}.heading{display:flex;justify-content:space-between;align-items:end;padding:32px 0 24px}.kicker{font-size:12px;color:var(--muted);margin-bottom:8px}.intro{font-size:14px;color:var(--muted)}.game{background:var(--card);border:1px solid var(--bd);border-radius:12px;overflow:hidden}.row{display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px;padding:16px 24px}label{display:flex;flex-direction:column;gap:4px;min-width:0;font-size:12px;color:var(--muted)}select{font-size:14px;width:100%;min-height:44px;padding:8px 12px;color:var(--fg);border:1px solid var(--bd);border-radius:6px;background:var(--card);cursor:pointer}select:disabled{opacity:.55}.wrap{position:relative;background:#527d79;isolation:isolate}canvas{width:100%;display:block;aspect-ratio:800/420;touch-action:none}.scene-caption{position:absolute;bottom:16px;right:20px;left:20px;display:flex;justify-content:space-between;align-items:center;pointer-events:none;color:#fff;text-shadow:0 1px 4px #15382f;font-size:12px}.scene-caption>span:first-child{font-size:16px;font-weight:600}#scene-detail{background:#203f35ed;border-radius:4px;padding:4px 12px;text-shadow:none}.controls{display:flex;gap:24px;align-items:center;justify-content:space-between;padding:24px}.feedback{min-width:0}#msg{font-size:16px;font-weight:600}.feedback p{font-size:12px;color:var(--muted);margin-top:8px}.cast-action{min-width:265px;text-align:center}#btn{width:100%;min-height:48px;font-size:16px;user-select:none;-webkit-user-select:none;touch-action:none}.cast-action>span{display:block;font-size:12px;color:var(--muted);margin-top:8px}kbd{font:inherit;border:1px solid var(--bd);border-radius:4px;padding:1px 6px}.journal{padding:32px 0 40px}.journal-heading{display:flex;align-items:end;justify-content:space-between;margin-bottom:20px}#stat{color:var(--muted);font-size:12px}.table-scroll{overflow-x:auto}#hist{width:100%;border-collapse:collapse;text-align:left;font-size:14px}#hist th{font-size:12px;font-weight:400;color:var(--muted);padding:8px 12px;border-bottom:1px solid var(--bd)}#hist td{padding:12px;border-bottom:1px solid var(--bd);white-space:nowrap}#hist .empty{text-align:center;white-space:normal;padding:28px;color:var(--muted);background:var(--soft);border:0}footer{display:flex;justify-content:space-between;border-top:1px solid var(--bd);padding:24px 0 32px;color:var(--muted);font-size:12px}footer>span:first-child{font-weight:600}#card{position:absolute;inset:0;display:none;align-items:center;justify-content:center;background:#122d3280;z-index:2}#card>div{background:var(--card);border-radius:12px;padding:32px;text-align:center;min-width:280px;box-shadow:0 16px 48px #142d3240}#card .small{color:var(--muted)}#card .big{font-size:32px;font-weight:600;line-height:1.2;margin:12px 0 8px}#cw{font-size:24px}#cp{color:var(--muted);margin:4px 0 20px}#card button{margin:0 4px}#tut{display:none;margin-bottom:16px;padding:16px 20px;border-radius:8px;background:#e8dfc8;color:#443c29;gap:16px;align-items:center;justify-content:space-between}#tt{max-width:700px}#tut>div:last-child{display:flex;gap:8px;flex-shrink:0}.hl{outline:3px solid #aa7a2d;outline-offset:-3px;border-radius:8px}.modal{position:fixed;inset:0;background:#112a2c99;display:none;align-items:center;justify-content:center;padding:24px;z-index:5}.mb{background:var(--card);color:var(--fg);border-radius:12px;padding:32px;max-width:640px;width:100%;max-height:88vh;overflow:auto;box-shadow:0 24px 80px #112a2c33}.modal-intro{color:var(--muted);margin:12px 0 24px}.mb h3{font-size:16px;font-weight:600;margin:24px 0 8px}.mb table{width:100%;border-collapse:collapse;font-size:14px}.mb td,.mb th{padding:12px 4px;border-bottom:1px solid var(--bd);text-align:left}.mb td:last-child{min-width:130px}.mb button{padding:8px 12px}.mb>.x{margin-top:24px;min-width:100px}.mb b{font-weight:600}.fl,.small{font-size:12px;color:var(--muted)}.fl{margin-top:4px}#shopmsg{min-height:20px;color:#a02f27;font-size:14px;margin-top:12px}
@media(prefers-color-scheme:dark){:root{color-scheme:dark;--bg:#17241f;--fg:#e7ece3;--muted:#b0bcb0;--card:#203129;--bd:#3d5042;--ac:#3e7155;--soft:#2b3d30}.brand svg{stroke:#a6b99a}#tut{background:#4a422c;color:#f0e5c8}}
@media(max-width:700px){body{padding:0 16px}.top{gap:16px;flex-wrap:wrap;padding:20px 0 12px}.brand{font-size:20px}.top nav{order:3;width:100%;margin:0;gap:0;justify-content:space-between}.top nav button{padding:8px 12px}.money{margin-left:auto;min-width:72px;padding-left:16px}.heading{padding:24px 0 16px}.intro{display:none}h1{font-size:24px}.row{padding:16px;gap:12px;grid-template-columns:1fr 1fr}.row label:first-child{grid-column:1/-1}.wrap{overflow:hidden}canvas{width:100%;max-width:100%}.scene-caption{left:12px;right:12px;bottom:12px}.scene-caption>span:first-child{font-size:14px}#scene-detail{font-size:12px;padding:4px 8px}.controls{padding:16px;flex-direction:column;gap:16px;align-items:stretch}.cast-action{min-width:0}.feedback p{margin-top:4px}.journal{padding:24px 0 32px}.journal-heading{gap:16px;align-items:center}h2{font-size:20px}.journal-heading .kicker{display:none}#stat{max-width:110px;text-align:right}footer{gap:16px}.mb{padding:20px;max-height:90vh}.modal{padding:12px}.mb td{font-size:12px}.mb td:last-child{min-width:104px}.mb button{padding:8px}.mb td:first-child{min-width:82px}.mb .fl{font-size:12px}#tut{flex-direction:column;align-items:start}#card>div{padding:20px;min-width:260px}#card .big{font-size:24px}}
.scene-caption{position:relative;inset:auto;background:#203f35;min-height:44px;padding:8px 20px;text-shadow:none;gap:12px}.scene-caption #scene-detail{background:transparent;padding:0;font-size:12px}.scene-caption>span:first-child{font-size:14px}@media(max-width:700px){.scene-caption{padding:8px 12px;gap:8px}.scene-caption #scene-detail{font-size:10px}}
.location-control{display:flex;flex-direction:column;gap:4px;min-width:0}.location-control>span{font-size:12px;color:var(--muted)}.location-control b{font-weight:400}.location-control button{display:flex;justify-content:space-between;align-items:center;text-align:left;padding:8px 12px}.location-modal{background:rgba(8,15,19,.82);padding:32px}.location-window{background:#252f3b;color:#f7f8fa;border:1px solid #536171;border-radius:16px;width:1240px;max-width:100%;max-height:92vh;overflow:auto;box-shadow:0 24px 80px #0008;padding:24px}.location-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;margin-bottom:24px}.location-heading>div{flex:1;text-align:center;padding-left:68px}.location-heading h2{font-size:28px;letter-spacing:-.02em;line-height:1.2;margin:4px 0 8px}.location-heading p{color:#c8d1db}.location-close{background:#5e536e;font-size:32px;line-height:1;padding:0;width:44px;flex-shrink:0}.location-close:hover{background:#756786}.location-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.location-option{background:#424f60;padding:16px;border-radius:12px;display:flex;flex-direction:column;min-width:0;border:2px solid transparent}.location-option.is-current{border-color:#bdcfae}.location-preview{width:100%;aspect-ratio:1.85;object-fit:cover;border-radius:10px;display:block}.location-option h3{font-size:20px;line-height:1.2;text-align:center;margin:12px 0 4px;font-weight:600}.location-habitat{font-size:12px;color:#e0e6ed;text-align:center;margin-bottom:16px}.fish-panel{background:#252f3b;border:1px solid #7f90a5;border-radius:10px;padding:12px 8px;margin-bottom:8px}.fish-panel h4{font-size:16px;line-height:1.3;text-align:center;margin:0 0 8px;font-weight:600}.popular-fish,.weight-fish{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;align-items:start}.weight-fish{grid-template-columns:repeat(2,minmax(0,1fr))}.location-fish{text-align:center;min-width:0;font-size:12px;font-weight:600;line-height:1.3}.location-fish svg{width:100%;height:68px;display:block}.location-fish span{display:block;overflow-wrap:anywhere}.location-fish small{display:block;color:#d7e1ec;font-size:12px;margin-top:4px;font-weight:400}.location-species{font-size:12px;color:#e0e6ed;margin:8px 0 16px;line-height:1.5}.location-option>button{margin-top:auto;background:#d5dfc9;color:#23382b;width:100%;padding:10px 8px}.location-option>button:hover{background:#edf3e5}.location-option>button[aria-pressed=true]{background:#b9cbaa}.location-note{font-size:12px;color:#c8d1db;text-align:center;margin-top:16px}@media(max-width:900px){.location-modal{padding:16px}.location-window{padding:16px}.location-list{gap:12px}.location-option{padding:12px}.location-heading h2{font-size:24px}.fish-panel h4{font-size:14px}}@media(max-width:700px){.location-control{grid-column:1/-1}.location-modal{padding:12px}.location-window{max-height:94vh;padding:16px}.location-heading{gap:12px;margin-bottom:16px}.location-heading>div{text-align:left;padding-left:0}.location-heading h2{font-size:20px;margin-top:0}.location-heading p{font-size:12px}.location-list{grid-template-columns:1fr;gap:16px}.location-preview{aspect-ratio:2.2}.location-fish svg{height:72px}.fish-panel h4{font-size:16px}.location-note{text-align:left}}
[hidden]{display:none!important}.top nav{flex-wrap:wrap}.top nav button[aria-pressed=true]{background:var(--soft);font-weight:600}.guide-summary{color:var(--muted);margin-top:12px;font-size:14px}.guide-intro{max-width:720px;color:var(--muted);margin-bottom:24px}.guide-tabs{display:flex;gap:8px;border-bottom:1px solid var(--bd);padding-bottom:12px}.guide-tabs button{background:transparent;color:var(--fg);transition:none}.guide-tabs button[aria-selected=true]{background:var(--ac);color:#fff}.guide-tabs button[aria-selected=false]{background:var(--soft);color:var(--fg)}.guide-tabs button[aria-selected=false]:hover{background:var(--bd)}.guide-tabs button[aria-selected=true]:hover{background:#244934;color:#fff}.guide-note{color:var(--muted);font-size:12px;margin:16px 0 24px}.guide-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;margin-bottom:40px}.guide-card{background:var(--card);border:1px solid var(--bd);border-radius:12px;overflow:hidden;scroll-margin:24px}.guide-illustration{height:140px;display:flex;align-items:center;justify-content:center;background:var(--soft)}.guide-illustration svg{width:220px;height:120px}.guide-card-body{padding:20px}.guide-card-title{display:flex;justify-content:space-between;gap:12px;align-items:start}.guide-card h3{font-size:20px;line-height:1.2;letter-spacing:-.02em;font-weight:600;margin:0}.guide-price{white-space:nowrap;text-align:right;font-size:16px;font-weight:600}.guide-price small{display:block;font-size:12px;color:var(--muted);font-weight:400}.guide-weight{font-size:12px;color:var(--muted);margin-top:8px}.guide-card dl{margin:20px 0 0}.guide-card dt{font-size:12px;color:var(--muted);margin-top:16px}.guide-card dd{margin:4px 0 0}.guide-links{display:flex;flex-wrap:wrap;gap:4px 12px}.guide-link{min-height:44px;padding:8px 0;background:transparent;color:var(--fg);font-weight:400;text-decoration:underline;text-decoration-color:var(--muted);text-underline-offset:4px}.guide-link:hover{background:var(--soft)}.guide-bait-card .guide-weight{margin-top:20px}@media(max-width:1000px){.top{gap:16px}.top nav button{padding:8px 12px}.guide-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.top nav{justify-content:flex-start;gap:4px}.guide-heading{align-items:start;gap:16px;flex-direction:column}.guide-grid{grid-template-columns:1fr;gap:16px}.guide-card-body{padding:20px}.guide-illustration{height:128px}.guide-intro{font-size:14px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{transition:none!important;animation:none!important}}
